import React from 'react';
import { CForm } from '@cloud-materials/common';
import type { Field } from '@cloud-materials/common/formily/core';

export default () => {
  const config = CForm.defineConfig({
    fields: [
      {
        name: 'A',
        title: 'A',
        initialValue: 0,
        decoratorOptions: {
          component: 'FormItem',
        },
        componentOptions: CForm.defineComponentOption('InputNumber'),
      },
      {
        name: 'B',
        title: 'B',
        visible: true,
        initialValue: 0,
        decoratorOptions: {
          component: 'FormItem',
        },
        componentOptions: CForm.defineComponentOption('InputNumber'),
      },
      {
        name: 'C',
        title: 'C=A+B',
        decoratorOptions: {
          component: 'FormItem',
        },
        componentOptions: CForm.defineComponentOption('Text'),
        reactions: field => {
          // 通过 query('name').take() 可以取出一个字段，然后修改字段的属性即可更新 UI
          const fieldA = field.query('A').take() as unknown as Field;
          const fieldB = field.query('B').take() as unknown as Field;
          field.content = fieldA.value + fieldB.value;

          // 如果要控制字段的显隐，可直接设置字段属性, eg
          // field.visible = fieldA.value === '1';
          // field.hidden = fieldB.value === '2';

          // 其他字段属性也直接修改 eg:
          // 即 field.xxx = xxx
        },
      },
    ],
  });

  return (
    <div style={{ width: '100%', maxHeight: 1500, overflow: 'auto' }}>
      <CForm config={config} defaultDecoratorProps={{ isFullPage: false }} />
    </div>
  );
};

import React from 'react';
import { CForm } from '@cloud-materials/common';
import type { Field } from '@cloud-materials/common/formily/core';
import { onFieldReact } from '@cloud-materials/common/formily/core';

export default () => {
  const config = CForm.defineConfig({
    effects: helper => {
      // 使用封装 helper 工具函数实现联动
      helper.effects.fieldsReactive({
        fieldNames: 'F',
        deps: ['D', 'E'],
        fieldCallback: ({ currField, depValues }) => {
          const { D: dValue = 0, E: eValue = 0 } = depValues || {};
          currField.content = dValue + eValue;
        },
      });

      // 使用原生 formily effect 联动
      // A 和 B 字段改变时修改 C 字段属性
      onFieldReact('C', field => {
        const fieldA = field.query('A').take() as unknown as Field;
        const fieldB = field.query('B').take() as unknown as Field;
        field.content = fieldA.value + fieldB.value;
      });
    },
    fields: [
      {
        name: 'A',
        title: 'A',
        initialValue: 0,
        decoratorOptions: CForm.defineDecoratorOptions('FormItem'),
        componentOptions: CForm.defineComponentOption('InputNumber'),
      },
      {
        name: 'B',
        title: 'B',
        visible: true,
        initialValue: 0,
        decoratorOptions: CForm.defineDecoratorOptions('FormItem'),
        componentOptions: CForm.defineComponentOption('InputNumber'),
      },
      {
        name: 'C',
        title: 'C=A+B',
        decoratorOptions: CForm.defineDecoratorOptions('FormItem'),
        componentOptions: CForm.defineComponentOption('Text'),
      },
      {
        name: 'D',
        title: 'D',
        initialValue: 0,
        decoratorOptions: CForm.defineDecoratorOptions('FormItem'),
        componentOptions: CForm.defineComponentOption('InputNumber'),
      },
      {
        name: 'E',
        title: 'E',
        visible: true,
        initialValue: 0,
        decoratorOptions: CForm.defineDecoratorOptions('FormItem'),
        componentOptions: CForm.defineComponentOption('InputNumber'),
      },
      {
        name: 'F',
        title: 'F=D+E',
        decoratorOptions: CForm.defineDecoratorOptions('FormItem'),
        componentOptions: CForm.defineComponentOption('Text'),
      },
    ],
  });

  return (
    <div style={{ width: '100%', maxHeight: 1500, overflow: 'auto' }}>
      <CForm config={config} defaultDecoratorProps={{ isFullPage: false }} />
    </div>
  );
};

