import React from 'react';
import type { DescriptionsProps, InputProps } from '@cloud-materials/common';
import { CForm, Descriptions, Input, InputNumber, Link, Alert, useCForm } from '@cloud-materials/common';
import { observer, useField } from '@cloud-materials/common/formily/react';
import type { CField } from '../interface';
import type { Field } from '@cloud-materials/common/formily/core';

interface CustomComponentProps {
  text?: string;
}
const CustomComponent = (props: CustomComponentProps) => {
  const { text } = props;
  return <div>{text}</div>;
};

const CustomComponent2 = observer((props: any) => {
  const { value, onChange } = props;
  const field = useField() as unknown as Field;
  // 使用 DataSource 获取取值范围
  const [{ min, max }] = field.dataSource || [];
  const form = useCForm();
  return (
    <div style={{ width: 600 }}>
      <div>
        <div>{`一个自定义组件，支持 value & onChange 即可。`}</div>
        <div>{`可使用useField 获取字段 & dataSource等，使用 useForm获取整个表单的引用`}</div>
        <Alert type="warning" content="注意，只有在表单中渲染时才能使用`useField` & `useForm`" />
        <Alert
          type="warning"
          content={
            <div>
              注意，需要使用
              <Link href="https://react.formilyjs.org/zh-CN/api/shared/observer" target="_blank">
                observer
              </Link>
              包裹，该组件才是响应式的，才能响应式获取表单其余字段属性/值等等。
            </div>
          }
        />
        <div>
          {`observer包裹后，可使用field.query(xxx).get('value')获取其余字段的值。并其余字段变更后，该组件会自动重新渲染。`}
        </div>
        <div>接入现成组件库的话，注意可使用 connect/mapProps/mapReadPretty API</div>
        <div>
          可参考
          <Link target="_blank" href="https://react.formilyjs.org/zh-CN/api/shared/connect">
            Formily connect 文档
          </Link>
        </div>
      </div>
      <InputNumber value={value} min={min} max={max} onChange={onChange} />
      <span>value: {value}</span>
      <div>
        Field Datasource
        <code>{JSON.stringify(field?.dataSource)}</code>
      </div>
      <div>
        Form Values
        <code>{JSON.stringify(form?.values)}</code>
      </div>
    </div>
  );
});

const CustomRectiveInputComponet = observer((props: InputProps) => {
  const field = useField() as unknown as CField;
  const placeholder = field.query('A').value();

  const { onChange } = props;
  return <Input onChange={onChange} placeholder={placeholder} />;
});

const CustomComponentValue = observer((props: DescriptionsProps) => {
  const field = useField() as unknown as CField;
  const form = useCForm();

  const otherField = form.query('CustomComponent2')?.take?.() as unknown as CField;
  const dataMap = [
    { label: '该Field的value字段', value: field.value },
    { label: '"自定义输入组件"的value字段', value: otherField.value },
    { label: '该字段的dataSource', value: JSON.stringify(field.dataSource) },
    { label: '"自定义输入组件"的dataSource', value: JSON.stringify(otherField.dataSource) },
    { label: '该field的任意一个字段(如visible)', value: String(field.visible) },
    { label: '从form的全局数据上获取值', value: form.data?.initConfigData },
  ];
  return <Descriptions layout="inline-horizontal" data={dataMap} style={{ padding: 10 }} {...props} />;
});

