import React from 'react';
import { CForm } from '@cloud-materials/common';
import { observer, useField } from '@cloud-materials/common/formily/react';
import type { Field } from '@cloud-materials/common/formily/core';

const CustomLayoutDecorator: React.FC<any> = props => {
  // 接受到的 chidren 为 <>{fields字字段}<>
  const { children } = props;
  // 使用自定义布局实现 flex 横向滚动
  return <div style={{ display: 'flex', width: '100%', overflowX: 'scroll' }}>{children}</div>;
};

const CustomComponent: React.FC<{ customProps: string }> = observer(props => {
  // chidren 为 componentOptions 传入的组件
  const { children, customProps } = props;

  const field = useField() as unknown as Field;

  return (
    <div>
      <div>{field.title}</div>
      {children}
      <div>我的爱好是: {field.value}</div>
      <div>额外补充: {customProps} </div>
    </div>
  );
});

export default () => {
  const config = CForm.defineConfig({
    fields: [
      {
        name: 'CustomLayoutDecorator',
        type: 'VoidField',
