          {
            name: 'name',
            title: '姓名',
            decoratorOptions: CForm.defineDecoratorOptions('FormItem'),
            componentOptions: CForm.defineComponentOption('Input', { style: { width: 200 } }),
          },
          {
            name: 'sex',
            title: '性别',
            decoratorOptions: CForm.defineDecoratorOptions('FormItem'),
            componentOptions: CForm.defineComponentOption('Select', { style: { width: 200 } }),
            dataSource: [
