              { label: '女', value: 'women' },
            ],
          },
          {
            name: 'age',
            title: '年龄',
            decoratorOptions: CForm.defineDecoratorOptions('FormItem'),
            componentOptions: CForm.defineComponentOption('InputNumber', { style: { width: 200 } }),
          },
          {
            name: 'interest',
