            componentOptions: CForm.defineComponentOption('Select'),
            dataSource: form => {
              const dataSourceField = form.query('setDataSouce').take() as unknown as Field;
              if (dataSourceField?.value) {
                try {
                  const dataSouce = JSON.parse(dataSourceField.value);
                  return dataSouce;
