import React, { useImperativeHandle, useRef, useState } from 'react';
import { Button, CForm } from '@cloud-materials/common';

const CustomComponent = React.forwardRef((_, ref) => {
  const [text, setText] = useState('初始文案，按钮点击后改为 xxxxxxxx');

  useImperativeHandle(ref, () => ({
    setText: (text: string) => {
      setText(text);
    },
  }));

  return <div>{text}</div>;
});

