import React, { useRef } from 'react';
import { CForm, Button } from '@cloud-materials/common';
import type { CForm as CFormType } from '@cloud-materials/common/es/CForm';

export default () => {
  const form = useRef<CFormType>();

  // fields 里面的元素就是一个个字段
  // 这里定义了三个字段
  const config = CForm.defineConfig({
    fields: [
      {
        name: 'A',
        title: 'A',
        decoratorOptions: CForm.defineDecoratorOptions('FormItem'),
        componentOptions: CForm.defineComponentOption('InputNumber'),
      },
      {
        name: 'B',
        title: 'B',
        decoratorOptions: CForm.defineDecoratorOptions('FormItem'),
        componentOptions: CForm.defineComponentOption('InputNumber'),
      },
      {
        name: 'Dynamic',
        type: 'VoidField',
        decoratorOptions: CForm.defineDecoratorOptions('DynamicFieldDecorator', {
          deps: ['A', 'B'],
          getDynamicFields: ({ depValues }) => {
            const A = Number(depValues?.A);
            const B = Number(depValues?.B);
            if (A > B) {
              return [
                {
                  name: 'dynamicA',
                  title: 'dynamicA',
                  componentOptions: CForm.defineComponentOption('Input'),
                  decoratorOptions: CForm.defineDecoratorOptions('FormItem'),
                },
              ];
            }
            if (A < B) {
              return [
                {
                  name: 'dynamicB',
                  title: 'dynamicB',
                  componentOptions: CForm.defineComponentOption('Select'),
                  decoratorOptions: CForm.defineDecoratorOptions('FormItem'),
                },
              ];
            }
            return [
              {
                name: 'dynamicC',
                title: 'dynamicC',
                componentOptions: CForm.defineComponentOption('InputNumber'),
                decoratorOptions: CForm.defineDecoratorOptions('FormItem'),
              },
            ];
          },
        }),
      },
    ],
  });

  return (
    <div>
      <div style={{ width: '100%', height: 180, overflow: 'auto' }}>
        <CForm ref={form} config={config} defaultDecoratorProps={{ isFullPage: false }} />
      </div>
      <Button
        type="primary"
        onClick={() => {
          form.current?.submit(values => {
            console.log('submit values', values);
          });
        }}
      >
        提交
      </Button>
    </div>
  );
};

