import type { ObjectField } from '@formily/core';
import { get } from 'lodash-es';
import type { CFormAsyncSelectFetchDataSource } from '../react/Components/CFormAsyncSelect/interface';

export default () => {
  function getResultData(param: string) {
    const arr = [...Array(100).keys()];
    const res: { label: string; value: string }[] = arr.map(item => ({
      label: param + '_label_' + item,
      value: param + '_value_' + item,
    }));
    return res;
  }

  function getLoadMoreList(
    page: number,
    pageSize: number,
    prefix: string,
    searchWord?: string,
  ): Promise<CFormAsyncSelectFetchDataSource> {
    const start = (page - 1) * pageSize;
    const end = page * pageSize;
    const list = getResultData(prefix + searchWord ?? '').slice(start, end);
    const res: CFormAsyncSelectFetchDataSource = {
      list,
      total: 100,
    };
    return new Promise(resolve => {
      setTimeout(() => {
        resolve(res);
      }, 1000);
    });
  }

  const config = CForm.defineConfig({
    initConfig: () => {
      return {
        values: {
          TrainModuleRelease: [
            {
              ModuleId: '_value_0',
              Version: '_value_0_value_0',
            },
          ],
        },
      };
    },
    fields: [
      {
        name: 'TrainModuleRelease',
        title: '关联组件',
        type: 'ArrayField',
        decoratorOptions: CForm.defineDecoratorOptions('FormItem'),
        componentOptions: CForm.defineComponentOption('ArrayItems'),
        fields: [
          {
            name: 'object',
            type: 'ObjectField',
            decoratorOptions: CForm.defineComponentOption('Space'),
            fields: [
              {
                name: 'ModuleId',
                decoratorOptions: CForm.defineDecoratorOptions('FormItem'),
                componentOptions: CForm.defineComponentOption('CFormAsyncSelect', {
                  addBefore: '组件',
                  showSearch: true,
                  autoLoad: true,
                  style: {
                    width: 220,
                  },
                  fetchData: ({ page, searchWord }) => {
                    return getLoadMoreList(page, 10, '', searchWord);
                  },
                }),
              },
              {
                name: 'Version',
                decoratorOptions: CForm.defineDecoratorOptions('FormItem'),
                componentOptions: CForm.defineComponentOption('CFormAsyncSelect', (_, parentField) => {
                  const index = (parentField as unknown as ObjectField)?.path?.segments?.[1];
                  return {
                    addBefore: '版本',
                    showSearch: true,
                    autoLoad: true,
                    style: {
                      width: 220,
                    },
                    deps: [`TrainModuleRelease.${index}.ModuleId`],
                    fetchData: ({ page, depValues, searchWord }) => {
                      console.log('fetchData-depValues', depValues);
                      const moduleId = get(depValues, `TrainModuleRelease.${index}.ModuleId`);
                      return getLoadMoreList(page, 10, moduleId ?? '', searchWord);
                    },
                  };
                }),
