import React from 'react';
import { CForm, Button } from '@cloud-materials/common';
import { ArrayTable } from '@cloud-materials/common/es/CForm';

const CustomAddition: React.FC<{ max?: number }> = props => {
  const { max = 99999 } = props;
  const { addItem, showAdd, disabled, title } = ArrayTable.useAddition!('push', {});
  // 数组实例，可获取目前的数组 field 实例
  const array = ArrayTable.useArray!();

  if (!showAdd) {
    return null;
  }

  // 当前数组的长度获取
  const curentCount = array.field.value?.length;

  return (
    <Button disabled={disabled || curentCount >= max} onClick={() => addItem()}>
      {title}
    </Button>
  );
};

CustomAddition.displayName = 'ArrayTableAddition';

const CustomRemove: React.FC<{ min: number }> = props => {
  const { removeItem, showRemove, disabled, index } = ArrayTable.useRemove!();
  console.log('当前 index', index);
  const array = ArrayTable.useArray!();
  if (!showRemove) return null;
  const currentCount = array.field.value?.length || 0;
  return (
    <Button disabled={disabled || currentCount <= props.min} onClick={() => removeItem()}>
      删除
    </Button>
  );
};

CustomRemove.displayName = 'CustomRemove';

