    fields: [
      {
        name: 'control',
        title: '控制A字段的数据加载切换',
        initialValue: true,
        decoratorOptions: CForm.defineDecoratorOptions('FormItem', { labelWidth: 200 }),
        dataSource: [
          { label: '加载数据', value: true },
          { label: '加载空数据', value: false },
