        type: 'Field',
        title: '单选',
        required: true,
        decoratorOptions: CForm.defineDecoratorOptions('FormItem'),
        description: '直接传入dataSource或者CTableSelect的data属性，没有loading效果',
        dataSource: form => {
          return form.data.table1;
        },
        initialValue: 'Jane Doe_1',
        componentOptions: CForm.defineComponentOption('CTableSelect', {
          type: 'radio',
          rowKey: 'name',
          columns: columnsConfig,
          rowSelection: {
            // 禁止可选方式二： 通过selectable ，薪水为22000的不可选
            selectable: ({ rowData }) => rowData.salary !== 22000,
          },
          filterOptions: [
            {
              name: 'email',
              visible: true,
              component: 'Input',
              componentProps: {
                placeholder: '请输入email',
              },
            },
            {
              name: 'name',
              component: 'CRadio',
              componentProps: {
                options: radioOptions,
              },
            },
            {
              name: 'salary',
              visible: true,
              component: 'Input',
              componentProps: {
                placeholder: '请输入salary',
              },
            },
          ],
          allValueOption: true,
        }),
      },
      {
        name: 'section2',
        title: '多选表格&&可全局禁止',
        type: 'VoidField',
        decoratorOptions: CForm.defineDecoratorOptions('Section'),
        fields: [
          {
            name: 'disabled',
            title: '切换下面表格的禁止态',
            initialValue: true,
            decoratorOptions: CForm.defineDecoratorOptions('FormItem', { labelWidth: 200 }),
            componentOptions: CForm.defineComponentOption('CRadio'),
            dataSource: [
              { label: '禁止选择', value: true },
              { label: '允许选择', value: false },
            ],
          },
          {
            name: 'table2',
            type: 'Field',
            title: '多选',
            decoratorOptions: CForm.defineDecoratorOptions('FormItem', form => ({
              extra: `继承了CTable大部分属性，可自由配置，包括toolbar，fetcher等。配置fetcher后可实现远程搜索 ||
              你选择了：${form.values['table2']?.join(',')}`,
            })),
            disabled: form => form.values['disabled'],
            // initialValue: ['Jane Doe_1', 'Alisa Ross_1'],
            componentOptions: CForm.defineComponentOption('CTableSelect', {
              type: 'checkbox',
              rowKey: 'name',
              columns: columnsConfig,
              allValueOption: { label: '全部数据' },
              pagination: true,
              renderSelectCell: (oriNode, __, { data }) => {
                if (data.salary === 7000) {
                  return (
                    <Popover content="你可以自定义传入想展示的内容，但是开启全选时仍会选中此行的值，如果想禁止选择该行，请配置data的disabled属性为true或者row">
                      <IconQuestionCircle />
                    </Popover>
                  );
                }

                return oriNode;
              },

              fetcher: async ({ pageSize, currentPage }) => {
                const { data, total } = await getData(currentPage, pageSize);
                return { data: data.map(info => ({ ...info })), total };
              },
              filterOptions: [
                {
                  name: 'name',
                  component: 'Select',
                  componentProps: {
                    options: radioOptions,
                    style: { width: 200 },
                  },
                },
              ],
              toolbar: {
                left: [{ name: '', component: () => <Link>我是toolbar的left</Link> }],
                right: [
                  { name: 'email', component: () => <Button>我是toolbar的right</Button> },
                  {
                    component: 'FunctionBtnList',
                    componentProps: {
                      btnList: [{ component: 'RefreshBtn' }],
                    },
                  },
                ],
              },
            }),
          },
        ],
      },
      {
        name: 'section3',
        title: '表格其它字段的获取&&联动',
        type: 'VoidField',
        decoratorOptions: CForm.defineDecoratorOptions('Section'),
        fields: [
          {
            name: 'People',
            title: '人员选择',
            decoratorOptions: CForm.defineDecoratorOptions('FormItem'),
            componentOptions: CForm.defineComponentOption('CTableSelect', {
              rowKey: 'name',
              columns: columnsConfig,
              mode: 'loadMore',
              fetcher: async ({ pageSize, currentPage }) => {
                const { data, total } = (await getData(currentPage, pageSize)) as { data: any[]; total: number };
                return { data, total, noMore: data.length < pageSize };
              },
            }),
          },
          {
            name: 'Salary',
            title: '你选择的人员的薪水',
            initialValue: true,
            decoratorOptions: CForm.defineDecoratorOptions('FormItem', { labelWidth: 200 }),
            componentOptions: CForm.defineComponentOption('Input'),
          },
        ],
      },
    ],
    effects: helper => {
      helper.effects.fieldsReactive({
        fieldNames: 'A',
        deps: 'control',
        fetchData: async ({ depValues }) => {
          if (depValues?.control) {
            const data = await getData();
            return data.data;
          } else {
            return new Promise(resolve => {
              setTimeout(() => {
                resolve([]);
              }, 500);
            });
          }
        },
        fieldCallback: [helper.fieldCallback.setDataSource()],
      });

      /** 表格其它字段的获取与联动 */
      helper.effects.fieldsReactive({
        fieldNames: 'Salary',
        deps: 'People',
        fieldCallback: ({ currField, depValues, form }) => {
          const peopleField = form.query('People')?.take() as Field;

          // 多选场景下表格的值是数组，单选时是字符串
          const peopleInfo = peopleField?.dataSource?.find(people => people.name === depValues?.People);
          currField.setValue(peopleInfo?.salary);
        },
      });
    },
    footer: {
      left: [{ buttonType: 'confirm' }],
    },
    onSubmit(values) {
      console.log(values);
    },
  });

  return (
    <div style={{ width: '100%', maxHeight: 1500, overflow: 'auto' }}>
      <CForm config={formConfig} />
    </div>
  );
};

