  }, []);

  const config = CForm.defineConfig({
    initConfig: async () => {
      return new Promise<any>(resolve => {
        setTimeout(() => {
          resolve({
            data: {
              currentTime: dayjs().format('YYYY-MM-DDTHH:mm:ss'),
            },
          });
        }, 500);
      });
    },
    effects: helper => {
      // ****** 字段的异步初始化处理：接口获取数据、设置 dataSource、设置默认值 **********
      helper.effects.fieldsInit({
        fieldNames: 'formType',
        fetchData: () => {
          return new Promise(resolve => {
            setTimeout(() => {
              resolve([
                {
                  value: 'form',
                  label: '普通表单',
                },
                {
                  value: 'formStep',
                  label: '步骤表单',
                },
              ]);
            }, 3000);
          });
        },
        fieldCallback: [helper.fieldCallback.setDataSource(), helper.fieldCallback.selectFirstByDataSource()],
      });

      helper.effects.fieldsInit({
        fieldNames: ['A', 'B', 'C'],
        fetchData: () => {
          return new Promise(resolve => {
            setTimeout(() => {
              resolve({
                A: '1C4G|2C8G|4C100G',
                B: '1-10',
                C: {
                  Regions: [
                    {
                      RegionId: 'cn-qingdao',
                      RegionName: '华北-青岛',
                    },
                    {
                      RegionId: 'cn-north-4',
                      RegionName: '华北4',
                    },
                  ],
                },
              });
            }, 1000);
          });
        },
        fieldCallback: [
          ({ currField, fetchResult }) => {
            switch (currField.path.entire) {
              case 'A': {
                const dataSource = fetchResult?.A.split('|').map((v: any) => ({ label: v, value: v })) || [];
                currField.dataSource = dataSource;
                currField.value = get(currField.dataSource, '[0].value');
                break;
              }
              case 'B': {
                const [min, max] = fetchResult?.B?.split('-') || [];
                currField.componentProps.min = min;
                currField.componentProps.max = max;
                currField.value = min;
                break;
              }
              case 'C': {
                const dataSource =
                  fetchResult?.C.Regions?.map((v: any) => ({ value: v.RegionId, label: v.RegionName })) || [];
                currField.dataSource = dataSource;
                currField.value = get(currField.dataSource, '[0].value');
                break;
              }
              default:
                break;
            }
          },
        ],
      });

      // ****** 多字段的联动依赖处理 ********
      helper.effects.fieldsReactive({
        deps: ['A', 'B'],
        fieldNames: ['D', 'E'],
        debounceWait: 2000,
        fetchData: ({ depValues }) => {
          console.log('11111');
          return new Promise(resolve => {
            setTimeout(() => {
              resolve({
                D: [
                  {
                    regionId: `${depValues?.A}-cn-qingdao-${depValues?.B}`,
                    regionName: `${depValues?.A}-青岛-${depValues?.B}`,
                  },
                  {
                    regionId: `${depValues?.A}-cn-north-${depValues?.B}`,
                    regionName: `${depValues?.A}-华北4-${depValues?.B}`,
                  },
                ],
                E: {
                  min: Number(depValues?.B),
                  max: Number(depValues?.B + 10),
                },
              });
            }, 2000);
          });
        },
        fieldCallback: ({ currField, fetchResult }) => {
          switch (currField.path.entire) {
            case 'D': {
              currField.dataSource = fetchResult?.D.map((item: any) => ({
                label: item.regionId,
                value: item.regionName,
              }));
              currField.value = get(currField.dataSource, '[0].value');
              break;
            }
            case 'E': {
              const { min, max } = fetchResult?.E || {};
              currField.componentProps.min = min;
              currField.componentProps.max = max;
              break;
            }
            default:
              break;
          }
        },
      });

      // ****** 字段的全局数据联动，每次 form.data 更新执行 ********
      helper.effects.formDataReactive({
        fieldNames: 'currentTime',
        fieldCallback: ({ depValues, currField }) => {
          currField.value = depValues?.currentTime;
        },
      });

      // ****** 字段的校验联动 ********
      helper.effects.validatorReactive(['password', 'confirmPassword']);

      // ****** section字段的自动隐藏，当其子字段全部被隐藏时 ********
      helper.effects.autoHiddenEmptySection('hiddenSection');

      // ****** 更多通用 helper.fieldCallback 工具函数 ********
      helper.effects.fieldsReactive({
        deps: ['switch'],
        fieldNames: 'F',
        fieldCallback: [
          // 开关开启，禁用 F
          helper.fieldCallback.checkDisableByDeps(depValues => Boolean(depValues.switch)),
        ],
      });

      helper.effects.fieldsReactive({
        deps: ['switch'],
        fieldNames: 'G',
        // 开关开启，清空 G 的值
        fieldCallback: [helper.fieldCallback.checkClearValueByDeps(depValues => Boolean(depValues.switch))],
      });
    },
    fields: [
      {
        name: 'asyncInit',
        title: '使用 helper 单个字段拉取接口初始化并设置数据源和选中第一个默认值',
        type: 'VoidField',
        decoratorOptions: CForm.defineDecoratorOptions('Section'),
        fields: [
          {
            name: 'formType',
            title: '表单类型',
            decoratorOptions: CForm.defineDecoratorOptions('FormItem'),
            componentOptions: CForm.defineComponentOption('CRadio'),
          },
        ],
      },
      {
        name: 'asyncBatchInit',
        title: '使用 helper 三个字段初始化调用同一接口拉取数据',
        type: 'VoidField',
        decoratorOptions: CForm.defineDecoratorOptions('Section'),
        fields: [
          {
            name: 'A',
            title: 'A',
            decoratorOptions: CForm.defineDecoratorOptions('FormItem'),
            componentOptions: CForm.defineComponentOption('Select'),
          },
          {
            name: 'B',
            title: 'B',
            decoratorOptions: CForm.defineDecoratorOptions('FormItem'),
            componentOptions: CForm.defineComponentOption('InputNumber'),
            description(form) {
              const field = form.query('B').take();
              return `B 的范围为 ${field?.componentProps.min} -  ${field?.componentProps.max}`;
            },
          },
          {
            name: 'C',
            title: 'C',
            decoratorOptions: CForm.defineDecoratorOptions('FormItem'),
            componentOptions: CForm.defineComponentOption('CRadio'),
          },
        ],
      },
      {
        name: 'batchReactive',
        title: '使用 helper 多个字段联动',
        type: 'VoidField',
        decoratorOptions: CForm.defineDecoratorOptions('Section'),
        fields: [
          {
            name: 'D',
            title: 'D',
            decoratorOptions: CForm.defineDecoratorOptions('FormItem'),
            componentOptions: CForm.defineDecoratorOptions('CRadio'),
          },
          {
            name: 'E',
            title: 'E',
            decoratorOptions: CForm.defineDecoratorOptions('FormItem'),
            componentOptions: CForm.defineDecoratorOptions('InputNumber'),
            description: form => {
              const field = form.query('E').take();
              return `E 的范围为 ${field?.componentProps.min} - ${field?.componentProps.max}`;
            },
          },
        ],
      },
      {
        name: 'dataReactive',
        title: '全局数据 data 响应式',
        type: 'VoidField',
        decoratorOptions: CForm.defineDecoratorOptions('Section'),
        fields: [
          {
            name: 'currentTime',
            title: '当前时间',
            decoratorOptions: CForm.defineDecoratorOptions('FormItem'),
            componentOptions: CForm.defineComponentOption('Text'),
          },
        ],
      },
      {
        name: 'validator',
        title: '互相触发校验字段',
        type: 'VoidField',
        decoratorOptions: CForm.defineDecoratorOptions('Section'),
        fields: [
          {
            name: 'password',
            title: '密码',
            decoratorOptions: CForm.defineDecoratorOptions('FormItem'),
            componentOptions: CForm.defineComponentOption('Password'),
          },
          {
            name: 'confirmPassword',
            title: '确认密码',
            decoratorOptions: CForm.defineDecoratorOptions('FormItem'),
            componentOptions: CForm.defineComponentOption('Password'),
            rules: {
              validator: ({ value, form, callback }) => {
                if (form.values['password'] === value) {
                  callback('');
                } else {
                  callback('两次密码不一致');
                }
              },
            },
          },
        ],
      },
      {
        name: 'hiddenH',
        title: '隐藏 H',
        decoratorOptions: CForm.defineDecoratorOptions('FormItem'),
        componentOptions: CForm.defineComponentOption('Switch'),
      },
      {
        name: 'hiddenSection',
        title: '所有子字段隐藏自动隐藏 Section',
        type: 'VoidField',
        decoratorOptions: CForm.defineDecoratorOptions('Section'),
        fields: [
          {
            name: 'H',
            title: 'H',
            decoratorOptions: CForm.defineDecoratorOptions('FormItem'),
            componentOptions: CForm.defineComponentOption('Input'),
            hidden: form => {
              return !!(form.query('hiddenH').take() as unknown as Field).value;
            },
          },
        ],
      },
      {
        name: 'others',
        title: '其他 helper 的例子',
        type: 'VoidField',
        decoratorOptions: CForm.defineDecoratorOptions('Section'),
        fields: [
          {
            name: 'switch',
            title: '开关',
            decoratorOptions: CForm.defineDecoratorOptions('FormItem'),
            componentOptions: CForm.defineComponentOption('Switch'),
          },
          {
            name: 'F',
            title: 'F',
            decoratorOptions: CForm.defineDecoratorOptions('FormItem'),
            componentOptions: CForm.defineComponentOption('Input'),
            description: '开关开启禁用 F',
          },
          {
            name: 'G',
            title: 'G',
            initialValue: 'xxxx',
            decoratorOptions: CForm.defineDecoratorOptions('FormItem'),
            componentOptions: CForm.defineComponentOption('Input'),
            description: '开关开启清空 G 的值',
          },
        ],
      },
    ],
    footer: {
      right: [{ buttonType: 'submit' }],
    },
    onSubmit(values) {
      return new Promise<void>(resolve => {
        setTimeout(() => {
          console.log(values);
          resolve();
        }, 2000);
      });
    },
  });

  return (
    <div style={{ width: '100%', maxHeight: 1500, overflow: 'auto' }}>
      <CForm config={config} ref={form} defaultDecoratorProps={{ isFullPage: false }} />
    </div>
  );
};

import { Button, CFormSchema } from '@cloud-materials/common';
import type { Form } from '@formily/core';
import React, { useRef } from 'react';

export default () => {
  const ref = useRef<Form<any>>(null);
  const schema = {
    type: 'object',
    properties: {
      username: {
        type: 'string',
        title: 'Username',
        required: true,
        'x-decorator': 'FormItem',
        'x-component': 'Input',
      },
      email: {
        type: 'string',
        title: 'Email',
        required: true,
        'x-validator': 'email',
        'x-decorator': 'FormItem',
        'x-component': 'Input',
      },
      oldPassword: {
        type: 'string',
        title: 'Old Password',
        required: true,
        'x-decorator': 'FormItem',
        'x-component': 'Password',
      },
      password: {
        type: 'string',
        title: 'New Password',
        required: true,
        'x-decorator': 'FormItem',
        'x-component': 'Password',
        'x-component-props': {
          checkStrength: true,
        },
        'x-reactions': [
          {
            dependencies: ['.confirm_password'],
            fulfill: {
              state: {
                selfErrors:
                  '{{$deps[0] && $self.value && $self.value !== $deps[0] ? "Confirm that the password does not match" : ""}}',
              },
            },
          },
        ],
      },
      confirm_password: {
        type: 'string',
        title: 'Confirm Password',
        required: true,
        'x-decorator': 'FormItem',
        'x-component': 'Password',
        'x-component-props': {
          checkStrength: true,
        },
        'x-reactions': [
          {
            dependencies: ['.password'],
            fulfill: {
              state: {
                selfErrors:
                  '{{$deps[0] && $self.value && $self.value !== $deps[0] ? "Confirm that the password does not match" : ""}}',
              },
            },
          },
        ],
      },
    },
  };
  return (
    <>
      <CFormSchema
        ref={ref}
        schemaField={{
          schema,
        }}
      />
      <Button
        onClick={() => {
          ref.current?.submit();
        }}
      >
        提交
      </Button>
    </>
  );
};
